package com.nigson.acceptance.cart;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import static org.assertj.core.api.Assertions.*;
public final class CartHttpAcceptance {
 private CartHttpAcceptance(){}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base)throws Exception{if(System.getenv("NIGSON_TEST_CART")==null)return;var sessions=app.getBean(JdbcSessionTrust.class);var cookies=new ArrayList<String>();var tokens=new ArrayList<String>();try(var fixture=new CartFixture(app.getBean(JdbcTemplate.class),app.getBean(org.springframework.transaction.PlatformTransactionManager.class))){var f=fixture.f;f.retail();for(UUID party:List.of(f.customer.party(),f.finance.party())){String issuer=f.jdbc.queryForObject("SELECT identity_issuer FROM commerce.party WHERE id=?",String.class,party);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String csrf=JdbcSessionTrust.opaque();tokens.add(csrf);String session=sessions.authenticate(flow.sessionId(),new SessionRecord(1,party,issuer,party.toString(),Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),csrf,SessionRecord.TokenState.READY));cookies.add("__Host-nigson-session="+session);}String root=base+"/api/v1/carts",cart=root+"/"+f.cart,line=cart+"/lines/"+f.sku,input="{\"marketId\":\""+f.market+"\"}";assertThat(send(http,HttpRequest.newBuilder(URI.create(cart)).GET()).statusCode()).isEqualTo(401);assertThat(send(http,HttpRequest.newBuilder(URI.create(cart)).header("Authorization","Bearer browser-token").GET()).statusCode()).isEqualTo(401);var existing=send(http,command(root,"POST",cookies.getFirst(),tokens.getFirst(),"create",input,null));assertThat(existing.statusCode()).as("create: %s",existing.body()).isEqualTo(201);assertThat(EventCodec.JSON.readTree(existing.body()).get("id").asString()).isEqualTo(f.cart.toString());assertThat(existing.headers().firstValue("ETag")).hasValue("\"0\"");assertThat(existing.headers().firstValue("Cache-Control")).hasValue("no-store");assertThat(send(http,HttpRequest.newBuilder(URI.create(cart)).header("Cookie",cookies.get(1)).GET()).statusCode()).isEqualTo(404);assertThat(send(http,command(line,"PUT",cookies.getFirst(),"wrong","bad-csrf","{\"quantity\":\"3\"}",0L)).statusCode()).isEqualTo(401);assertThat(send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"zero","{\"quantity\":\"0\"}",0L)).statusCode()).isEqualTo(400);assertThat(send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"unknown","{\"quantity\":\"3\",\"price\":\"0\"}",0L)).statusCode()).isEqualTo(400);var changed=send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"put","{\"quantity\":\"3\"}",0L));assertThat(changed.statusCode()).as("put: %s",changed.body()).isEqualTo(200);assertThat(changed.headers().firstValue("ETag")).hasValue("\"1\"");assertThat(send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"put","{\"quantity\":\"3\"}",0L)).body()).isEqualTo(changed.body());assertThat(send(http,command(line,"PUT",cookies.getFirst(),tokens.getFirst(),"stale","{\"quantity\":\"4\"}",0L)).statusCode()).isEqualTo(412);var current=send(http,HttpRequest.newBuilder(URI.create(cart)).header("Cookie",cookies.getFirst()).GET());assertThat(current.body()).isEqualTo(changed.body());assertThat(send(http,HttpRequest.newBuilder(URI.create(cart+"?owner="+f.customer.party())).header("Cookie",cookies.getFirst()).GET()).statusCode()).isEqualTo(400);var removed=send(http,command(line,"DELETE",cookies.getFirst(),tokens.getFirst(),"delete",null,1L));assertThat(removed.statusCode()).as("delete: %s",removed.body()).isEqualTo(204);assertThat(removed.body()).isEmpty();assertThat(removed.headers().firstValue("ETag")).hasValue("\"2\"");assertThat(send(http,command(line,"DELETE",cookies.getFirst(),tokens.getFirst(),"delete",null,1L)).statusCode()).isEqualTo(204);var registry=app.getBean(io.micrometer.core.instrument.MeterRegistry.class);assertThat(registry.get("nigson.cart.commands").tag("operation","SET").counter().count()).isEqualTo(1);assertThat(registry.get("nigson.cart.commands").tag("operation","REMOVE").counter().count()).isEqualTo(1);}finally{for(String cookie:cookies)sessions.logout(cookie.substring(cookie.indexOf('=')+1));}}
 private static HttpRequest.Builder command(String uri,String method,String cookie,String csrf,String key,String body,Long version){var request=HttpRequest.newBuilder(URI.create(uri)).header("Cookie",cookie).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",key);if(version!=null)request.header("If-Match","\""+version+"\"");if(body!=null)request.header("Content-Type","application/json");return request.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body));}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(10)).build(),HttpResponse.BodyHandlers.ofString());}
}
